from playwright.sync_api import sync_playwright
OUT=pathlib.Path(__file__).resolve().parents[2]/'docs/adventures-v10';result={'checks':[],'environment':'Managed Chromium SwiftShader. Independent extracted Preview 09 reference on 5182; no physical device test.'}
def check(name,ok,detail=None):
 result['checks'].append({'name':name,'passed':bool(ok),'detail':detail});(OUT/'bedroom-compat.json').write_text(json.dumps(result,indent=2)+'\n');print('PASS'if ok else'FAIL',name,detail or '',flush=True);assert ok,name
with sync_playwright()as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox','--use-angle=swiftshader','--enable-unsafe-swiftshader']);pages=[]
 for port in[5182,5175]:
  g=b.new_page(viewport={'width':640,'height':480},has_touch=True,is_mobile=True);g.set_default_timeout(120000);g.goto(f'http://127.0.0.1:{port}/adventures.html?test=1');g.wait_for_function('window.adventure?.ready');g.locator('#enter').click();g.evaluate('window.requestAnimationFrame=()=>0');g.wait_for_timeout(100);pages.append(g)
 old,current=pages
 source=old.evaluate('''async()=>{const g=adventure.game,e=g.landscape.entrances.find(e=>e.kind==='cottage');Object.assign(g.player,{x:e.x,z:e.z});await g.enterRoom(e);const table=g.objects.find(p=>p.id==='upstairs-table');table.x+=.25;table.yaw=.3;table.id='keep-old-upstairs-desk';g.renderObjects();const r=g.interior.solids.find(s=>s.ramp).ramp;g.cameraYaw=0;for(const[x,z]of[[0,r.cz+r.length/2+.5],[r.cx,r.cz+r.length/2+.5],[r.cx,r.cz-r.length/2-.6],[0,r.cz-r.length/2-.6]]){for(let i=0;i<2000;i++){const dx=x-g.player.x,dz=z-g.player.z,n=Math.hypot(dx,dz);if(n<.07)break;g.update(1/120,{x:dx/n*.6,z:dz/n*.6,run:false});}g.velocity.set(0,0);}await g.session.save();return{backup:g.session.export(),objects:JSON.stringify(g.objects),inside:g.data.inside.id,y:g.player.y}}''')
 current.evaluate('(text)=>adventure.session.import(text)',source['backup']);kept=current.evaluate('''()=>{const g=adventure.game;return{objects:JSON.stringify(g.objects),inside:g.data.inside.id,y:g.player.y,layout:g.data.layout,beds:g.objects.filter(p=>p.asset==='furniture-bedsingle').length}}''');check('Preview 09 furnished upper-floor save imports without replacing decorations or adding a bedroom',kept['objects']==source['objects']and kept['inside']==source['inside']and kept['y']>2.99 and kept['layout']==5 and kept['beds']==0,kept)
 reentered=current.evaluate('''async()=>{const g=adventure.game,id=g.data.inside.id,before=JSON.stringify(g.objects);await g.leaveRoom();const e=g.landscape.entrances.find(e=>e.id===id);await g.enterRoom(e);return before===JSON.stringify(g.objects)&&g.data.layout===5}''');check('revisiting the retained house still uses its saved template and edits',reentered)
 # Create a separate fresh current valley/bedroom. It must not overwrite the imported version-09 room.
 fresh=current.evaluate('''async()=>{const g=adventure.game,old=g.session.current.id;await g.leaveRoom();await g.session.create('vale');const e=g.landscape.entrances.find(e=>e.kind==='cottage');Object.assign(g.player,{x:e.x,z:e.z});await g.enterRoom(e);return{different:g.session.current.id!==old,bed:g.objects.some(p=>p.asset==='furniture-bedsingle'),backup:g.session.export()}}''');check('fresh current house gets a bedroom in an independent world copy',fresh['different']and fresh['bed'])
 rejected=old.evaluate('''async text=>{const g=adventure.game,before=JSON.stringify(g.snapshot()),id=g.session.current.id,count=(await g.session.store.list()).length;let error=false;try{await g.session.import(text)}catch(e){error=true}return error&&id===g.session.current.id&&before===JSON.stringify(g.snapshot())&&count===(await g.session.store.list()).length}''',fresh['backup']);check('older Preview 09 refuses new furniture/layout backup without changing source or creating partial import',rejected)
 b.close()
